pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 ts1, uint256 ts2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 d1 = uint256(keccak256(abi.encode(ts1)));
        uint256 d2 = uint256(keccak256(abi.encode(ts2)));
        vm.warp(ts1);
        vm.roll(1);
        uint256 r1 = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(r1 != 0);
        vm.deal(actor, 100 ether);
        vm.prank(actor);
        c.play{value: 10}();

        vm.warp(ts2);
        vm.roll(2);
        uint256 r2 = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(r2 != 0);
        vm.prank(actor);
        c.play{value: 10}();

        assertTrue(c.pot() == 20);
    }
}
